//! Matrix family rules: shared detection types, unique `RuleMeta` per id.
//!
//! Generated by `scripts/gen_matrix_rules.py`. Re-run after catalog edits.

use vue_vet_core::{
  Confidence, FactKinds, FactRef, ReactiveBindingKind, ReactiveReadKind, Rule, RuleContext,
  RuleMeta, ScriptKind, Severity, TrackingScopeKind,
};

use crate::rules::support::{
  binding_path, effect_family, is_readonly_kind, unconditional_self_triggers, write_path,
};

struct BoundaryRule {
  meta: &'static RuleMeta,
  scope_kind: TrackingScopeKind,
  read_kind: ReactiveReadKind,
  scope_label: &'static str,
  reason: &'static str,
}

impl Rule for BoundaryRule {
  fn meta(&self) -> &'static RuleMeta {
    self.meta
  }

  fn fact_kinds(&self) -> FactKinds {
    FactKinds::TRACKING_SCOPE
  }

  fn run_on(&self, fact: FactRef<'_>, context: &mut RuleContext<'_>) {
    let FactRef::TrackingScope { scope, .. } = fact else {
      return;
    };
    if scope.kind != self.scope_kind {
      return;
    }
    for read in &scope.reads {
      if read.kind != self.read_kind {
        continue;
      }
      if self.read_kind == ReactiveReadKind::Conditional {
        let already = scope.reads.iter().any(|candidate| {
          candidate.kind == ReactiveReadKind::Unconditional
            && candidate.span.offset < read.span.offset
            && candidate.binding == read.binding
            && candidate.property == read.property
        });
        if already {
          continue;
        }
      }
      let path = binding_path(read);
      context.report(
        self.meta(),
        read.span.clone(),
        format!(
          "`{path}` is read {reason} inside {label}, so it is not a reliable dependency",
          reason = self.reason,
          label = self.scope_label
        ),
        Some(format!(
          "Read `{path}` synchronously in {label}, or use explicit `watch` sources.",
          label = self.scope_label
        )),
      );
    }
  }
}

macro_rules! boundary_rule {
  ($static_name:ident, $id:literal, $doc:literal, $scope:ident, $read:ident, $label:literal, $reason:literal) => {
    static $static_name: BoundaryRule = BoundaryRule {
      meta: &RuleMeta {
        id: $id,
        category: "reactivity",
        default_severity: Severity::Warning,
        confidence: Confidence::High,
        documentation: $doc,
      },
      scope_kind: TrackingScopeKind::$scope,
      read_kind: ReactiveReadKind::$read,
      scope_label: $label,
      reason: $reason,
    };
  };
}

