struct AfterAwaitCallRule {
  meta: &'static RuleMeta,
  callee: &'static str,
}

impl Rule for AfterAwaitCallRule {
  fn meta(&self) -> &'static RuleMeta {
    self.meta
  }

  fn run_once(&self, context: &mut RuleContext<'_>) {
    let mut findings = Vec::new();
    for block in &context.script().blocks {
      if block.kind != ScriptKind::Setup || block.top_level_await_ends.is_empty() {
        continue;
      }
      let Some(first_await_end) = block.top_level_await_ends.first().copied() else {
        continue;
      };
      for call in &block.calls {
        if call.callee != self.callee || call.span.offset < first_await_end {
          continue;
        }
        findings.push(call.span.clone());
      }
    }
    for span in findings {
      context.report(
        self.meta(),
        span,
        format!(
          "`{}` is registered after a top-level `await`, so it will not bind to this instance",
          self.callee
        ),
        Some(format!(
          "Move `{}` before the first top-level `await`, or register it in a synchronous setup path.",
          self.callee
        )),
      );
    }
  }
}

macro_rules! after_await_call_rule {
  ($static_name:ident, $id:literal, $doc:literal, $callee:literal) => {
    static $static_name: AfterAwaitCallRule = AfterAwaitCallRule {
      meta: &RuleMeta {
        id: $id,
        category: "correctness",
        default_severity: Severity::Warning,
        confidence: Confidence::High,
        documentation: $doc,
      },
      callee: $callee,
    };
  };
}

