struct WatchCallbackTrackingRule;

impl Rule for WatchCallbackTrackingRule {
  fn meta(&self) -> &'static RuleMeta {
    &RuleMeta {
      id: "vue-vet/reactivity/no-watch-callback-as-tracking-scope",
      category: "reactivity",
      default_severity: Severity::Warning,
      confidence: Confidence::High,
      documentation: "rules/reactivity/no-watch-callback-as-tracking-scope",
    }
  }

  fn run_once(&self, context: &mut RuleContext<'_>) {
    let mut findings = Vec::new();
    for block in &context.script().blocks {
      let scopes = &block.reactivity_graph.scopes;
      let mut index = 0;
      while index + 1 < scopes.len() {
        let Some(sources) = scopes.get(index) else {
          break;
        };
        let Some(callback) = scopes.get(index + 1) else {
          break;
        };
        if sources.kind == TrackingScopeKind::WatchSources
          && callback.kind == TrackingScopeKind::WatchCallback
          && sources.reads.is_empty()
          && !callback.reads.is_empty()
        {
          findings.push(callback.span.clone());
        }
        index += 1;
      }
    }
    for span in findings {
      context.report(
        self.meta(),
        span,
        "reactive reads in a `watch` callback are not tracked for invalidation".into(),
        Some(
          "List dependencies in the `watch` source argument; the callback is a side-effect sink."
            .into(),
        ),
      );
    }
  }
}

static P_WATCH_CALLBACK_TRACKING: WatchCallbackTrackingRule = WatchCallbackTrackingRule;

struct DestructureSourceRule {
  meta: &'static RuleMeta,
  source: &'static str,
  message: &'static str,
  help: &'static str,
  pinia_store: bool,
}

impl Rule for DestructureSourceRule {
  fn meta(&self) -> &'static RuleMeta {
    self.meta
  }

  fn fact_kinds(&self) -> FactKinds {
    FactKinds::SCRIPT_DESTRUCTURE
  }

  fn run_on(&self, fact: FactRef<'_>, context: &mut RuleContext<'_>) {
    let FactRef::ScriptDestructure { destructure, .. } = fact else {
      return;
    };
    let matched = if self.pinia_store {
      let name = destructure.source_call.as_str();
      name.starts_with("use") && name.ends_with("Store")
    } else {
      destructure.source_call == self.source
    };
    if !matched {
      return;
    }
    context.report(
      self.meta(),
      destructure.span.clone(),
      self.message.into(),
      Some(self.help.into()),
    );
  }
}

macro_rules! destructure_rule {
  ($static_name:ident, $id:literal, $doc:literal, $source:literal, $message:literal, $help:literal, $pinia:expr) => {
    static $static_name: DestructureSourceRule = DestructureSourceRule {
      meta: &RuleMeta {
        id: $id,
        category: "reactivity",
        default_severity: Severity::Warning,
        confidence: Confidence::High,
        documentation: $doc,
      },
      source: $source,
      message: $message,
      help: $help,
      pinia_store: $pinia,
    };
  };
}

destructure_rule!(
  I_REACTIVE_DESTRUCTURE,
  "vue-vet/reactivity/no-reactive-destructure",
  "rules/reactivity/no-reactive-destructure",
  "reactive",
  "destructuring `reactive()` loses reactivity for the pulled fields",
  "Keep the reactive object, or use `toRefs` / `toRef`.",
  false
);
