struct RefOperandRule {
  meta: &'static RuleMeta,
  kinds: &'static [ReactiveBindingKind],
  label: &'static str,
}

impl Rule for RefOperandRule {
  fn meta(&self) -> &'static RuleMeta {
    self.meta
  }

  fn fact_kinds(&self) -> FactKinds {
    FactKinds::SCRIPT_OPERAND
  }

  fn run_on(&self, fact: FactRef<'_>, context: &mut RuleContext<'_>) {
    let FactRef::ScriptOperand { block_kind, operand } = fact else {
      return;
    };
    let Some(block) = context.script().blocks.iter().find(|block| block.kind == block_kind) else {
      return;
    };
    let Some(binding) =
      block.reactivity_graph.bindings.iter().find(|binding| binding.name == operand.name)
    else {
      return;
    };
    if !self.kinds.contains(&binding.kind) {
      return;
    }
    context.report(
      self.meta(),
      operand.span.clone(),
      format!(
        "`{}` is a {} object used as an operand; unwrap with `.value` (or `toValue`)",
        operand.name, self.label
      ),
      Some(format!(
        "Use `{}.value` (or `toValue({})`) when reading the inner value.",
        operand.name, operand.name
      )),
    );
  }
}

macro_rules! ref_operand_rule {
  ($static_name:ident, $id:literal, $doc:literal, $label:literal, [$($kind:ident),+]) => {
    static $static_name: RefOperandRule = RefOperandRule {
      meta: &RuleMeta {
        id: $id,
        category: "reactivity",
        default_severity: Severity::Warning,
        confidence: Confidence::High,
        documentation: $doc,
      },
      kinds: &[$(ReactiveBindingKind::$kind),+],
      label: $label,
    };
  };
}

ref_operand_rule!(
  I_REF_AS_OPERAND,
  "vue-vet/reactivity/no-ref-as-operand",
  "rules/reactivity/no-ref-as-operand",
  "ref",
  [Ref, ShallowRef, CustomRef, ToRef, TemplateRef]
);
ref_operand_rule!(
  I_MODEL_REF_AS_OPERAND,
  "vue-vet/reactivity/no-model-ref-as-operand",
  "rules/reactivity/no-model-ref-as-operand",
  "defineModel ref",
  [ModelRef]
);
ref_operand_rule!(
  I_COMPUTED_AS_OPERAND,
  "vue-vet/reactivity/no-computed-as-operand",
  "rules/reactivity/no-computed-as-operand",
  "computed ref",
  [Computed]
);

struct ReadonlyMutationRule;

impl Rule for ReadonlyMutationRule {
  fn meta(&self) -> &'static RuleMeta {
    &RuleMeta {
      id: "vue-vet/reactivity/no-readonly-mutation",
      category: "reactivity",
      default_severity: Severity::Warning,
      confidence: Confidence::High,
      documentation: "rules/reactivity/no-readonly-mutation",
    }
  }

  fn fact_kinds(&self) -> FactKinds {
    FactKinds::SCRIPT_MEMBER_WRITE
  }

  fn run_on(&self, fact: FactRef<'_>, context: &mut RuleContext<'_>) {
    let FactRef::ScriptMemberWrite { block_kind, write } = fact else {
      return;
    };
    let Some(block) = context.script().blocks.iter().find(|block| block.kind == block_kind) else {
      return;
    };
    let Some(binding) =
      block.reactivity_graph.bindings.iter().find(|binding| binding.name == write.object)
    else {
      return;
    };
    if !is_readonly_kind(binding.kind) {
      return;
    }
    context.report(
      self.meta(),
      write.span.clone(),
      format!("`{}` is readonly and should not be mutated", write.object),
      Some("Mutate the source reactive state instead of a readonly projection.".into()),
    );
  }
}

static I_READONLY_MUTATION: ReadonlyMutationRule = ReadonlyMutationRule;

